arguments.command:
cat > /tmp/askpass-rachel.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s\n' "x-access-token" ;;
  *) printf '%s\n' "$GITHUB_TOKEN" ;;
esac
EOF
chmod 700 /tmp/askpass-rachel.sh
cd /tmp/friend-rachel-talk && git -c core.askPass=/tmp/askpass-rachel.sh push -q origin HEAD:refs/heads/friend/rachel && echo PUSHED_OK && git ls-remote origin refs/heads/friend/rachel
